WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, account_type ORDER BY balance DESC, id) AS row_num FROM accounts) t WHERE row_num = 1) SELECT s.id, s.customer_id, s.account_type, s.opened_date, (SELECT MAX(x.balance) FROM accounts x WHERE x.customer_id = s.customer_id) AS max_account_balance FROM latest s ORDER BY max_account_balance, customer_id DESC
